        for k, pt in zip(key, prefix_tuple):
            if k != pt:
                return False

        return True

    filtered_keys:List[Union[str,bytes]] = []
    def _add_to_filtered_keys(key):
        if isinstance(key, (str, bytes)):
            filtered_keys.append(key)

    for k in keys:
        if isinstance(k, tuple):
            if filter_prefix_tuple(k):
