                    tail = host[address_end + 1 :]


                    if len(tail) and tail[0] == ":":

                        port = tail[1:]
                    else:

                        port = default_port

                elif self.__class__.valid_ip(host):

                    server = host
                    port = default_port

                else:

                    server, port = host.rsplit(":", 1)

            else:
                server = host
                port = default_port

            return server, port


