            "Content-Type": "application/json"
        }

        data = {
            "from_path": recipe.file_path,
            "to_path": "%s/%s%s" % (
                os.path.dirname(recipe.file_path),
                new_name,
                os.path.splitext(recipe.file_path)[1]
            )
        }

        r = requests.post(url, headers=headers, data=json.dumps(data))

        return r.json()
