gs_windows_binary = None
def Ghostscript(tile, size, fp, scale=1):
    """Render an image using Ghostscript"""


    decoder, tile, offset, data = tile[0]
    length, bbox = data


    scale = int(scale) or 1
    orig_size = size
    orig_bbox = bbox
    size = (size[0] * scale, size[1] * scale)
    bbox = [bbox[0], bbox[1], bbox[2] * scale, bbox[3] * scale]


    import tempfile, os, subprocess

    file = tempfile.mktemp()


    command = ["gs",
               "-q",
               "-g%dx%d" % size,
               "-r%d" % (72*scale),
               "-dNOPAUSE -dSAFER",
               "-sDEVICE=ppmraw",
               "-sOutputFile=%s" % file,
            ]

    if gs_windows_binary is not None:
        if gs_windows_binary is False:
            raise WindowsError('Unable to locate Ghostscript on paths')
        command[0] = gs_windows_binary


    try:
        gs = subprocess.Popen(command, stdin=subprocess.PIPE, stdout=subprocess.PIPE)

        if bbox[0] != 0 or bbox[1] != 0:
            gs.stdin.write(("%d %d translate\n" % (-bbox[0], -bbox[1])).encode('ascii'))
        fp.seek(offset)
        while length > 0:
            s = fp.read(8192)
            if not s:
                break
            length = length - len(s)
            gs.stdin.write(s)
        gs.stdin.close()
        status = gs.wait()
